files./sasjs/drive/files/home/sasjsadmin/progr:
/**
  @file
  @brief A program to try in the demo

  Studio runs JavaScript on this host, so `Run` on a .sas file reports that SAS
  needs a server - which is the truth about a static site, and the reason this
  build is a demonstration rather than a deployment.
**/

data work.class;
  set sashelp.class;
  where age > 13;
run;

files./sasjs/drive/files/home/sasjsadmin/run.j:
/**
  @file
  @brief A program that DOES run in this browser

  Press Run in Studio: the service worker executes this file, the same way
  sasjs/server would execute it, and the log and webout appear in their tabs.
**/

const rows = [
  { name: 'Alice', age: 14 },
  { name: 'Bob', age: 15 },
  { name: 'Carol', age: 13 }
]

console.log(`Read ${rows.length} rows`)

webout(rows.filter((row) => row.age > 13))
